// Pre-computed high-precision digital stipple dot matrix world map
// Standard Natural Earth Robinson/Equirectangular projection matching reference style:
// Americas (Left), Europe & Africa (Center), Asia & Oceania (Right)

export const MATRIX_COLS = 210;
export const MATRIX_ROWS = 95;
export const LAT_MIN = -58;
export const LAT_MAX = 78;

export function latLonToMatrix(lat: number, lon: number): { col: number; row: number } {
  const normLon = ((lon + 180) % 360) / 360;
  const col = Math.round(normLon * MATRIX_COLS * 10) / 10;
  const normLat = (LAT_MAX - lat) / (LAT_MAX - LAT_MIN);
  const row = Math.round(normLat * (MATRIX_ROWS - 1) * 10) / 10;
  return { col, row };
}

